const LADDER = /^If you can['’]t get [^:]{2,40}: [^:]+\.$/;
const FIRST_PERSON = /\b(i|me|my|we|our|us)\b/i;
const PRICE = /\$|\b(price|prices|cost|costs|cheap|cheaper|expensive|budget|dollars?|save|savings|deal)\b/i;
