/bin/zsh -lc "node --input-type=module <<'JS'
import { readFileSync, writeFileSync } from 'node:fs';
const path = 'server/kristy_perimeter_kb.json';
const original = readFileSync(path, 'utf8');
const kb = JSON.parse(original);
const ids = ['potato_chips', 'tortilla_chips', 'crackers', 'frozen_fries', 'frozen_nuggets', 'snack_bars', 'popcorn'];
const before = new Map(ids.map(id => [id, structuredClone(kb.entries.find(e => e.id === id))]));
const byId = id => kb.entries.find(e => e.id === id);
const skip = 'Seed oils to skip: sunflower, safflower, canola, soybean, corn, and cottonseed.';
const avocado = 'Skip avocado oil too: the label cannot prove the oil is pure.';
const source = file => readFileSync(file, 'utf8').match(/"'^url:'"\\s*(\\S+)/m)[1];
const sources = [
  { name: 'Dr. Cate Shanahan: The Hateful Eight seed oils', url: source('docs/sources/concerns/pantry/shanahan-hateful-eight.md') },
  { name: 'Weston A. Price Foundation: FAQ, fats and oils', url: source('docs/sources/concerns/pantry/wapf-faq-fats-and-oils.md') },
];
const oilTips = {
  potato_chips: 'Read the ingredient list for the frying fat; take chips cooked in olive oil, coconut oil, tallow or lard.',
  tortilla_chips: 'Check the frying fat in the ingredients; choose masa chips cooked in olive oil, coconut oil, tallow or lard.',
  crackers: 'Read the ingredient list for oil; take crackers made with olive oil, coconut oil or butter.',
  frozen_fries: 'The bag’s ingredient list names the frying or par-frying oil. Choose tallow, olive oil, coconut oil or no added oil.',
  frozen_nuggets: 'Find the frying or par-frying oil in the ingredient list. Take nuggets with tallow, olive oil, coconut oil or no added oil.',
  snack_bars: 'Find the oil in the ingredient list; take bars made with olive oil, coconut oil or butter.',
  popcorn: 'Microwave bags and ready-popped bags name their oil in the ingredient list; skip bags that list seed oil.',
};
for (const id of ids) {
  const e = byId(id);
  e.buying_tips.splice(1, 0, oilTips[id], skip);
  e.watch_out.push(avocado);
  e.detail += ' Choosing these fats and skipping seed oils and avocado oil is Kristy’s standard.';
  e.sources.push(...sources);
}
Object.assign(byId('potato_chips'), {
  decision: 'Sliced potato chips in olive oil, coconut oil or tallow.',
  cart_pick: 'Sliced potato chips cooked in olive oil',
});
Object.assign(byId('tortilla_chips'), {
  decision: 'Masa tortilla chips in olive oil, coconut oil or tallow.',
  cart_pick: 'Masa tortilla chips cooked in olive oil',
});
Object.assign(byId('frozen_fries'), {
  decision: 'Frozen fries in tallow, olive oil or coconut oil.',
  cart_pick: 'Frozen fries cooked in tallow',
  kristy_take: 'A short list of potatoes, tallow, olive oil or coconut oil, and salt is the standard here. At home, starchy Russets fry crisp once rinsed of starch and dried. Home cooks freeze fries after the first fry, then do the second from frozen.',
  pick_steps: [
    'Read the bag’s list for potatoes, tallow, olive oil or coconut oil, and salt.',
    'A bag with no added oil also fits; compare what else is listed beyond potatoes and salt.',
  ],
});
const popcorn = byId('popcorn');
popcorn.decision = 'Plain popcorn kernels, popped at home in coconut oil.';
popcorn.buying_tips[3] = 'Buy plain kernels to pop at home in coconut oil, butter or tallow, then salt to taste.';
popcorn.pick_steps[0] = 'Pop plain kernels at home in coconut oil, butter or tallow; add salt to taste.';
const pinPath = 'server/test/acceptance/twoLinePin.js';
let pinText = readFileSync(pinPath, 'utf8');
const start = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const end = pinText.indexOf('\\n};', start) + 2;
const pins = JSON.parse(pinText.slice(start, end));
for (const id of ids) {
  const e = byId(id);
  for (const [field, value] of Object.entries(e)) if (JSON.stringify(value) "'!== JSON.stringify(before.get(id)[field])) pins[id][field] = value;
  console.log(id + '"': ' + Object.keys(pins[id]).join(', '));
}
pinText = pinText.slice(0, start) + JSON.stringify(pins, null, 2) + pinText.slice(end);
pinText = pinText.replace(/const CONCERN = new Set\\(\\[(["'^'"\\n]+)\\]\\);/, (_, list) => "'`const CONCERN = new Set([${list}, ${ids.map(id => `'"'"'${id}'"'"'`).join('"', ')}]);"'`);
writeFileSync(path, JSON.stringify(kb, null, 2) + '"'\\n');
writeFileSync(pinPath, pinText);
const reviewPath = 'docs/do-lines-review.md';
let review = readFileSync(reviewPath, 'utf8');
for (const id of ids) {
  const e = byId(id);
  if (e.decision "'!== before.get(id).decision) {
    review = review.split('"'\\n').map(line => {
      if ("'!line.startsWith('"'| "'`'"' + id + '"'` |'"')) return line;
      const cells = line.split('|');
      cells[3] = ' ' + e.decision + ' ';
      if (id === 'frozen_fries') cells[4] = ' Read the ingredient list for the oil used before freezing. ';
      return cells.join('|');
    }).join('\\n');
  }
}
writeFileSync(reviewPath, review);
JS"

