import { spawn } from 'node:child_process';
const child = spawn('npm', ['test'], { stdio: ['ignore', 'pipe', 'pipe'] });
let output = '';
child.stdout.on('data', chunk => { output += chunk; });
child.stderr.on('data', chunk => { output += chunk; });
child.on('close', code => {
  const lines = output.split('\\n');
  console.log(lines.filter(line => /"'^ℹ |''^✖|''^not ok|''^# (tests|pass|fail|duration)/.test(line)).join('"'\\n'));
